/// The codebase the session `key` of `pr` was asked about: the head commit
/// in its key, even after a newer push (ADR-0008 D4). `fallback` for a key
/// of another form.
fn codebase_of<K: CodeSource>(code: &K, pr: &PrRef, key: &SessionKey, fallback: &str) -> K::Code {
    let revision = key
        .0
        .strip_prefix(&key_prefix(pr))
        .filter(|head| !head.is_empty())
        .unwrap_or(fallback);
    code.at(revision)
}

fn history(path: &str) -> Command {
    // `path` comes from the model and has already passed
    // a check that rejects absolute paths, `..`, `\`,
    // control characters and `:`.
    let mut cmd = Command::new("git");
    cmd.args(["log", "--oneline", path]);
    cmd
}

use futures::{channel::{mpsc, oneshot}, StreamExt};

async fn drive(data: &Vec<String>) {
    let (tx, mut rx) = mpsc::unbounded::<(usize, oneshot::Sender<String>)>();
    let tool = async move {
        let (reply, answer) = oneshot::channel();
        tx.unbounded_send((0, reply)).unwrap();
        answer.await.unwrap()
    };
    let out = tool.await;
    while let Some((i, reply)) = rx.next().await {
        reply.send(data[i].clone()).unwrap();
    }
    println!("{out}");
}
